import React, { useState } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { useAuth } from '../../context/AuthContext';

const Header = () => {
  const { user, logout, isAuthenticated, hasRole } = useAuth();
  const navigate = useNavigate();
  const [isMenuOpen, setIsMenuOpen] = useState(false);

  const handleLogout = () => {
    logout();
    navigate('/');
    setIsMenuOpen(false);
  };

  const toggleMenu = () => {
    setIsMenuOpen(!isMenuOpen);
  };

  const closeMenu = () => {
    setIsMenuOpen(false);
  };

  return (
    <header className="header">
      <div className="container">
        <div className="header-content">
          {/* Logo */}
          <div className="logo">
            <Link to="/" onClick={closeMenu}>
              <h1>FoodTruck Hub</h1>
            </Link>
          </div>

          {/* Mobile menu toggle */}
          <button 
            className={`mobile-toggle ${isMenuOpen ? 'active' : ''}`}
            onClick={toggleMenu}
            aria-label="Toggle navigation menu"
          >
            <span></span>
            <span></span>
            <span></span>
          </button>

          {/* Navigation */}
          <nav className={`nav ${isMenuOpen ? 'nav-open' : ''}`}>
            <ul className="nav-list">
              <li><Link to="/" onClick={closeMenu}>Home</Link></li>
              <li><Link to="/vendors" onClick={closeMenu}>Find Vendors</Link></li>
              
              {isAuthenticated() ? (
                <>
                  {hasRole('ROLE_VENDOR') && (
                    <>
                      <li><Link to="/vendor-dashboard" onClick={closeMenu}>Dashboard</Link></li>
                      <li><Link to="/vendor-profile" onClick={closeMenu}>Profile</Link></li>
                      <li><Link to="/application-status" onClick={closeMenu}>Applications</Link></li>
                    </>
                  )}
                  
                  {hasRole('ROLE_ADMIN') && (
                    <>
                      <li><Link to="/admin-dashboard" onClick={closeMenu}>Admin Dashboard</Link></li>
                      <li><Link to="/admin/vendors" onClick={closeMenu}>Manage Vendors</Link></li>
                      <li><Link to="/admin/applications" onClick={closeMenu}>Manage Applications</Link></li>
                    </>
                  )}
                  
                  <li className="user-info">
                    <span>Welcome, {user?.username}</span>
                  </li>
                  <li>
                    <button onClick={handleLogout} className="logout-btn">
                      Logout
                    </button>
                  </li>
                </>
              ) : (
                <>
                  <li><Link to="/login" onClick={closeMenu}>Login</Link></li>
                  <li><Link to="/register" onClick={closeMenu}>Register</Link></li>
                </>
              )}
            </ul>
          </nav>
        </div>
      </div>
    </header>
  );
};

export default Header;
